double
CVolatilityTrailing::CalculateSimpleTR(
const
MqlRates
&rates[],
int
start_idx,
int
period)
  {
int
size =
ArraySize
(rates);
if
(start_idx + period >= size)
return
0.0
;
double
sum =
0.0
;
for
(
int
i =
0
; i < period; i++)
     {
int
idx = start_idx + i;
if
(idx +
1
>= size)
break
;
double
high       = rates[idx].high;
double
low        = rates[idx].low;
double
prev_close = rates[idx +
1
].close;
double
tr         =
MathMax
(high - low,
MathMax
(
MathAbs
(high - prev_close),
MathAbs
(low - prev_close)));
      sum += tr;
     }
return
(period >
0
) ? (sum / period) :
0.0
;
  }
